package dev.dothome;
import android.graphics.*;
import android.view.*;
import org.json.*;
import java.util.*;
import java.text.*;

/** Shared preview/live artwork, with separate renderers for each local widget family. */
final class WidgetArtwork extends View {
 final HomeActivity a;final JSONObject item;final boolean preview;final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);final RectF r=new RectF();
 WidgetArtwork(HomeActivity a,JSONObject x,boolean preview){super(a);this.a=a;item=x;this.preview=preview;setLayerType(View.LAYER_TYPE_HARDWARE,null);setContentDescription(x.optString("type")+" widget");}
 int ink,paper,secondary;float w,h,u;
 void text(Canvas c,String value,float x,float y,float size,int color,boolean mono){p.setColor(color);p.setStyle(Paint.Style.FILL);p.setTypeface(mono?Typeface.create("monospace",0):Typeface.create("sans-serif-medium",0));p.setTextSize(size);c.drawText(value,x,y,p);}
 String fit(String value,float size,float max){p.setTextSize(size);if(p.measureText(value)<=max)return value;while(value.length()>1&&p.measureText(value+"…")>max)value=value.substring(0,value.length()-1);return value+"…";}
 @Override protected void onDraw(Canvas c){w=getWidth();h=getHeight();u=Math.min(w,h);int style=item.optInt("style");boolean inverted=style==1;paper=inverted?a.fg:a.card;ink=inverted?a.bg:a.fg;secondary=inverted?a.bg:a.muted;if(style==2)paper=a.dark()?0x99181818:0x99e2ded6;p.setStyle(Paint.Style.FILL);p.setColor(paper);r.set(0,0,w,h);c.drawRoundRect(r,a.dp(26),a.dp(26),p);String type=item.optString("type");float pad=Math.min(a.dp(18),w*.12f),size=Math.min(a.dp(15),u*.16f);Date now=preview?new GregorianCalendar(2026,9,25,10,8).getTime():new Date();
  switch(type){
   case "clock":if(style==1){float radius=Math.min(w*.35f,h*.38f),cx=w/2,cy=h/2;p.setColor(ink);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(1.5f));c.drawCircle(cx,cy,radius,p);for(int n=0;n<12;n++){double angle=n*Math.PI/6;float x=(float)Math.sin(angle),y=(float)-Math.cos(angle);p.setStrokeWidth(n%3==0?a.dp(3):a.dp(1));c.drawLine(cx+x*radius*.84f,cy+y*radius*.84f,cx+x*radius*.94f,cy+y*radius*.94f,p);}Calendar time=Calendar.getInstance();time.setTime(now);hand(c,cx,cy,radius*.52f,(time.get(Calendar.HOUR)%12+time.get(Calendar.MINUTE)/60f)*30,ink,a.dp(4));hand(c,cx,cy,radius*.75f,time.get(Calendar.MINUTE)*6,ink,a.dp(2));hand(c,cx,cy,radius*.8f,time.get(Calendar.SECOND)*6,a.accent,a.dp(1));p.setStyle(Paint.Style.FILL);p.setColor(a.accent);c.drawCircle(cx,cy,a.dp(4),p);}else{String value=new SimpleDateFormat(android.text.format.DateFormat.is24HourFormat(a)?"HH:mm":"hh:mm",Locale.US).format(now);if(style==0)dots(c,value,pad,h*.22f,w-pad*2,h*.5f,ink);else text(c,value,pad,h*.64f,Math.min(w*.24f,h*.52f),ink,false);text(c,new SimpleDateFormat("EEE, d MMM",Locale.getDefault()).format(now).toUpperCase(),pad,h-pad,Math.min(size,w*.055f),secondary,true);}break;
   case "date":text(c,new SimpleDateFormat("EEE",Locale.getDefault()).format(now).toUpperCase(),pad,pad+size,size,secondary,true);text(c,new SimpleDateFormat("dd",Locale.getDefault()).format(now),pad,h-pad,Math.min(h*.55f,w*.47f),ink,false);text(c,new SimpleDateFormat("MMM",Locale.getDefault()).format(now).toUpperCase(),w*.58f,h-pad,size,ink,true);break;
   case "battery":float percent=preview?76:a.battery;float cx=w*.3f,cy=h*.52f,rr=Math.min(w*.2f,h*.29f);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(5));p.setColor(inverted?0x44333333:0x44555555);r.set(cx-rr,cy-rr,cx+rr,cy+rr);c.drawArc(r,0,360,false,p);p.setColor(ink);c.drawArc(r,-90,percent*3.6f,false,p);p.setStyle(Paint.Style.FILL);text(c,Math.round(percent)+"%",w*.53f,h*.61f,Math.min(w*.19f,h*.3f),ink,false);if(w>a.dp(130))text(c,a.charging?"CHARGING":"BATTERY",pad,h-pad,Math.min(size,a.dp(10)),secondary,true);break;
   case "photo":p.setColor(inverted?a.card:0xff77736d);r.set(pad,pad,w-pad,h-pad);c.drawRoundRect(r,style==1?u/2:a.dp(18),style==1?u/2:a.dp(18),p);p.setColor(paper);Path landscape=new Path();landscape.moveTo(pad,h-pad);landscape.lineTo(w*.42f,h*.37f);landscape.lineTo(w*.64f,h*.65f);landscape.lineTo(w*.78f,h*.46f);landscape.lineTo(w-pad,h-pad);landscape.close();c.drawPath(landscape,p);p.setColor(ink);c.drawCircle(w*.7f,h*.3f,u*.06f,p);text(c,preview?"PHOTO PREVIEW":"Choose a photo",pad,h-pad,Math.min(size,a.dp(11)),ink,true);break;
   case "media":p.setColor(inverted?a.card:a.bg);r.set(pad,pad,pad+h*.46f,pad+h*.46f);c.drawRoundRect(r,a.dp(12),a.dp(12),p);text(c,"♫",pad+h*.13f,pad+h*.34f,h*.3f,ink,false);text(c,"Now playing",pad+h*.55f,pad+size,Math.min(size,w*.07f),ink,false);text(c,"Your music",pad+h*.55f,pad+size*2.5f,Math.min(size,w*.06f),secondary,false);text(c,"‹       Ⅱ       ›",pad,h-pad,Math.min(w*.095f,h*.2f),ink,false);break;
   case "breathing":float progress=preview?.5f:(float)((Math.sin(System.currentTimeMillis()/2600.0)+1)/2);float radius=u*(.16f+.11f*progress);p.setColor(inverted?a.card:0xff44413c);c.drawCircle(w/2,h*.48f,radius+a.dp(12),p);p.setColor(ink);c.drawCircle(w/2,h*.48f,radius,p);text(c,preview?"BREATHE":progress>.5?"BREATHE IN":"BREATHE OUT",pad,h-pad,Math.min(size,w*.075f),ink,true);break;
   case "torch":case "bluetooth":case "sound":case "dnd":String glyph=type.equals("torch")?"ϟ":type.equals("bluetooth")?"ᛒ":type.equals("sound")?"♫":"☾";p.setColor(inverted?a.card:a.bg);c.drawCircle(w/2,h*.43f,u*.28f,p);text(c,glyph,w*.35f,h*.56f,u*.43f,ink,false);if(w>a.dp(100))text(c,type.toUpperCase(),pad,h-pad,Math.min(size,a.dp(10)),ink,true);break;
   case "compass":float degrees=preview?315:a.heading;float rad=u*.29f;p.setColor(ink);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(a.dp(1));c.drawCircle(w/2,h*.45f,rad,p);p.setStyle(Paint.Style.FILL);c.save();c.rotate(-degrees,w/2,h*.45f);p.setColor(a.accent);Path arrow=new Path();arrow.moveTo(w/2,h*.45f-rad*.8f);arrow.lineTo(w/2-rad*.18f,h*.45f);arrow.lineTo(w/2+rad*.18f,h*.45f);arrow.close();c.drawPath(arrow,p);c.restore();text(c,Math.round(degrees)+"°",pad,h-pad,Math.min(size*1.5f,w*.2f),ink,true);break;
   default:String label=type.equals("agenda")?"QUICK LOOK":type.equals("usage")?"SCREEN TIME":type.toUpperCase();String value=type.equals("notes")?item.optString("text",preview?"Make room for what matters.":"Tap to write a note"):type.equals("agenda")?(preview?"10:30 · Your next event":a.agenda):type.equals("usage")?(preview?"1h 24m":a.usage):type.equals("countdown")?(item.optLong("deadline")==0?"Set a date":Math.max(0,(item.optLong("deadline")-System.currentTimeMillis()+86399999)/86400000)+" days"):"Tap to configure";text(c,label,pad,pad+size*.7f,Math.min(size,a.dp(11)),secondary,true);float valueSize=Math.min(a.dp(22),Math.min(w*.12f,h*.27f));text(c,fit(value,valueSize,w-pad*2),pad,h*.66f,valueSize,ink,false);if(type.equals("countdown")&&h>a.dp(100))text(c,item.optString("name","A day to remember"),pad,h-pad,size*.8f,secondary,false);
  }
  if(!preview&&a.foreground&&isShown())postInvalidateDelayed(type.equals("breathing")?40:type.equals("compass")?120:1000);
 }
 void hand(Canvas c,float x,float y,float length,float angle,int color,float stroke){p.setColor(color);p.setStrokeWidth(stroke);p.setStrokeCap(Paint.Cap.ROUND);c.drawLine(x,y,x+(float)Math.sin(Math.toRadians(angle))*length,y-(float)Math.cos(Math.toRadians(angle))*length,p);}
 void dots(Canvas c,String value,float x,float y,float width,float height,int color){String[] patterns={"111101101101111","010110010010111","111001111100111","111001111001111","101101111001001","111100111001111","111100111101111","111001001001001","111101111101111","111101111001111"};float unit=Math.min(width/18f,height/5);for(char ch:value.toCharArray()){int columns=ch==':'?1:3;for(int row=0;row<5;row++)for(int col=0;col<columns;col++){boolean on=ch==':'?(row==1||row==3):patterns[ch-'0'].charAt(row*3+col)=='1';p.setStyle(Paint.Style.FILL);p.setColor(on?(ch==':'?a.accent:color):0x22555555);c.drawCircle(x+(col+.5f)*unit,y+(row+.5f)*unit,unit*.29f,p);}x+=(columns+1)*unit;}}
}
